-- ═════════════════════════════════════════════════════════════════════════════
-- Carga de la línea L5 (L5 - Modernización de la Gestión Administrativa) del "FOR-DE-144 Consolidado. 2026.xlsx"
-- 35 indicadores con su formulación y su seguimiento, en las mismas columnas que usa el sistema.
--
-- Antes de ejecutar:
--   1. Haz un respaldo de la base de datos.
--   2. @formulario es el id del formulario "Plan de Acción (2026)" (en tu base es 1; compruébalo en la tabla formularios).
--   3. @ef es el estado en que quedan los indicadores:
--        2 = PUBLICADOS en Formulación (aparecen en Seguimiento con sus datos de seguimiento)  ← por defecto
--        0 = BORRADORES de Formulación (hay que publicarlos después)
--
-- Los ids nuevos se calculan a partir del mayor id actual (@base), así que no pisa ningún registro existente.
-- ═════════════════════════════════════════════════════════════════════════════
SET NAMES utf8mb4;
SET @formulario = 1;
SET @ef = 2;
SET @base = (SELECT COALESCE(MAX(id), 0) FROM formulacion_144);

START TRANSACTION;


COMMIT;
