INSERT INTO formulacion_144
 (id, formulario_id, nombre_borrador, anio, linea_estrategica, objetivo, estrategia, motor_desarrollo, proyecto, meta_resultado, ponderacion_proyectos, actividad_proyecto, ponderacion_actividades, responsable_formulacion, id_indicador, gestionado_facultades, nombre_indicador, formula_medicion, frecuencia_medicion, unidad_medida, tipo_medicion, descripcion_indicador, planes_institucionales, linea_base_meta, anio_base_meta, meta_s1, meta_s2, meta_programada, meta_ejecutada, porcentaje_avance, semestre1_seguimiento, semestre2_seguimiento, logros, limites, observacion_estado, acciones_fortalecimiento, estado_formulacion, estado_seguimiento, solicitud_estado_formulacion, solicitud_estado_seguimiento, semaforo_etapa_formulacion, semaforo_etapa_seguimiento, semaforo_rechazo_etapa_formulacion, semaforo_rechazo_etapa_seguimiento, fecha_publicacion_formulacion, creado_por)
VALUES
(@base+1, @formulario, 'Ingresos de autogestión', 2026, 'Modernización de la Gestión Administrativa', 'Fortalecer la gestión administrativa, el uso eficiente de los recursos financieros, humanos y tecnológicos, la modernización y el mantenimiento de la infraestructura con enfoque a la sostenibilidad ambiental, como apoyo al mejoramiento de las funciones misionales y la prestación de servicios para el desarrollo de la Universidad, y así propiciar la inclusión, la calidad educativa, el bienestar del talento humano, la transparencia y la equidad.', '5. Mejorar la gestión de los recursos para garantizar la sostenibilidad financiera mediante el incremento de los ingresos por autogestión y búsqueda de fuentes alternativas de financiación.', 'Fortalecimiento institucional', 'Mejoramiento y efectividad de procesos administrativos y académicos', 'Incrementar la participación de los ingresos por venta de servicios a un 20% del total del presupuesto', 10.00, 'Apoyar administrativamente la eficiencia de los procesos relacionados con venta de servicios', 15.00, 'Dpto. de Gestión Financiera', 'PDI', '0', 'Ingresos de autogestión', '(Ingresos presupuestados para venta de servicios por año / total de ingresos corrientes recaudados anuales) *100', 'Anual', 'Porcentaje', 'Último valor reportado', '', '[]', '7%', 10, '0%', '10%', '10.00', '5.00', 50.00, 5.00, NULL, 'Al corte de junio 30 de 2026, el indicador de Ingresos de Autogestión presenta una ejecución del 5% frente del total recaudado por autogestión frente  los ingresos corrientes recaudados. \n\nIngresos por autogestión:  $11.522.257.239\nIngresos corrientes caudados: 210.461.526.139\n\nEs importante mencionar que los ingresos presupuestados son de $36.628.765.101', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+2, @formulario, 'Recaudo de cuentas por cobrar', 2026, 'Modernización de la Gestión Administrativa', 'Fortalecer la gestión administrativa, el uso eficiente de los recursos financieros, humanos y tecnológicos, la modernización y el mantenimiento de la infraestructura con enfoque a la sostenibilidad ambiental, como apoyo al mejoramiento de las funciones misionales y la prestación de servicios para el desarrollo de la Universidad, y así propiciar la inclusión, la calidad educativa, el bienestar del talento humano, la transparencia y la equidad.', '6. Fortalecer el perfil patrimonial de la institución.', 'Fortalecimiento institucional', 'Mejoramiento y efectividad de procesos administrativos y académicos', 'Actualización y recuperación de cartera', 10.00, 'Fomentar el recaudo de cuentas por cobrar', 15.00, 'Dpto. de Gestión Financiera', 'PA', '0', 'Recaudo de cuentas por cobrar', '(Saldos de cuentas por cobrar/ ingresos operacionales *365)', 'Anual', 'Unidad', 'Límite', 'Días rotación de cartera', '[]', '39', 39, '0', '39', '39.00', '96.00', 0.00, NULL, 96.00, 'Al cierre del segundo trimestre de 2026, el indicador de recaudo de cuentas por cobrar registró un resultado de 26,44 días\n\nRecaudo de Cuentas por Cobrar: (Saldo de Cuentas por Cobrar / Ingresos Operacionales) × 365\n= (59.462.073.650,89 / 224.880.782.308,46) × 365\n= 0,2644 × 365\n= 96 días', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+3, @formulario, 'Tiempo promedio de pago', 2026, 'Modernización de la Gestión Administrativa', 'Fortalecer la gestión administrativa, el uso eficiente de los recursos financieros, humanos y tecnológicos, la modernización y el mantenimiento de la infraestructura con enfoque a la sostenibilidad ambiental, como apoyo al mejoramiento de las funciones misionales y la prestación de servicios para el desarrollo de la Universidad, y así propiciar la inclusión, la calidad educativa, el bienestar del talento humano, la transparencia y la equidad.', '6. Fortalecer el perfil patrimonial de la institución.', 'Fortalecimiento institucional', 'Mejoramiento y efectividad de procesos administrativos y académicos', 'Optimizar los pagos a proveedores', 10.00, '', 15.00, 'Dpto. de Gestión Financiera', 'PA', '0', 'Tiempo promedio de pago', '(N° de cuentas por pagar/ N° de cuentas pagadas * 365)', 'Anual', 'Unidad', 'Límite', '', '[]', '0', 40, '0', '40', '40.00', '0.00', 0.00, NULL, NULL, 'En revisión para crear un indicador que muestre la eficiencia del proceso de tesorería en la gestión de pagos', '', 'El indicador tiempo promedio de pago (N° de cuentas por pagar/ N° de cuentas pagadas * 365); se encuentra en revisión para crear un indicador que muestre la eficiencia del proceso de tesorería en la gestión de pagos. La propuesta de esta revisión se presentará a la jefa del Depto de Gestión Financiera y al jefe de tesorería para tener su aval.', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+4, @formulario, 'Implementación y seguimiento del Plan Institucional de Archivos de la Entidad ­PINAR', 2026, 'Modernización de la Gestión Administrativa', 'Fortalecer la gestión administrativa, el uso eficiente de los recursos financieros, humanos y tecnológicos, la modernización y el mantenimiento de la infraestructura con enfoque a la sostenibilidad ambiental, como apoyo al mejoramiento de las funciones misionales y la prestación de servicios para el desarrollo de la Universidad, y así propiciar la inclusión, la calidad educativa, el bienestar del talento humano, la transparencia y la equidad.', '9. Fortalecer la administración y ejecución de los planes, programas y proyectos propendiendo por el desarrollo de las actividades misionales fundamentada en principios de eficiencia, transparencia, equidad y calidad de servicio.', 'Fortalecimiento institucional', 'Mejoramiento y efectividad de procesos administrativos y académicos', 'Ejecución del Plan Institucional de Archivos de la Entidad ­PINAR,  orientado a la mejora de los elementos importantes para la Planeación Estratégica y Gestión Documental  en cumplimiento a las directrices del Archivo General de la Nación.', 10.00, 'Realizar seguimiento al cumplimiento de la ejecución del Plan Institucional de Archivos de la universidad­PINAR,', 10.00, 'Secretaría General', 'PA', '0', 'Implementación y seguimiento del Plan Institucional de Archivos de la Entidad ­PINAR', '(N° de acciones desarrolladas para la  implementación del PINAR / N° de acciones contempladas en el  PINAR)*100', 'Anual', 'Porcentaje', 'Último valor reportado', 'Para el cumplimiento de las acciones contempladas en los proyectos establecidos en el mapa de ruta de la implementación del Plan Institucional de Archivo PINAR para la vigencia 2025, se tienen en cuenta que el documento dispone de ocho proyectos, estos cuentan con 38 actividades las cuales son las acciones que se deben llevar a cabo para la implementación y seguimiento del PINAR.\n\nPara la ejecucion y seguimiento de los proyectos (Elaboración y  reformulación  de  Procedimientos, Instructivos y formatos para la Gestión  Documental , Formulaciòn e implementacion de la Politica Cero Papel y elaboracion de las tablas de valoracion documental (tvd ) dispuestos en el mapa de ruta de la implementacion del pinar\n proyectados a mediano plazo 2025, se establecieron las siguientes actividades:\n\n1-Dar seguimiento a la elaboración y/o reformulación de un procedimiento o instructivo para cada subproceso de la gestion documental\n2-Socialización y publicación de los procedimientos o instructivos.\n3-Implementación y seguimiento de los procedimientos e instructivos\n4-Levantamiento de un diagnóstico de la impresión de documentos en papel, cantidad de impresoras, consumo de papel, consumo de tóner, entre otros\n5-Formulación de la Política Cero Papel\n6-Aprobación de la política Cero Papel\n7-Socialización de la política, incluida su publicación en Web\n8-Compilación de Información Institucional para la creacion de las tablas de valoracion documental.\n9-Preparación y formulación del instrumento (tabla de valoracion documental).\n10-Aprobación del instrumento archivístico respectivo.', '[]', '39%', 44, '0%', '44%', '44.00', '39.00', 88.64, 39.00, NULL, 'En el primer semestre de la vigencia se lograron desarrollar las siguientes subactividades para poder llevar a cabo las actividades dispuestas en el PINAR sobre la Política Cero Papel, tales como: Diseño y redacción del borrador propuesto, socialización propuesta a las partes interesadas (Comité Interno de Archivo), remisión para viabilidad técnica y jurídica del documento final y actualmente está para aprobación por los órganos competentes CSU en su segundo debate.', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+5, @formulario, 'Implementación y seguimiento del sistema integrado de conservación (SIC).', 2026, 'Modernización de la Gestión Administrativa', 'Fortalecer la gestión administrativa, el uso eficiente de los recursos financieros, humanos y tecnológicos, la modernización y el mantenimiento de la infraestructura con enfoque a la sostenibilidad ambiental, como apoyo al mejoramiento de las funciones misionales y la prestación de servicios para el desarrollo de la Universidad, y así propiciar la inclusión, la calidad educativa, el bienestar del talento humano, la transparencia y la equidad.', '9. Fortalecer la administración y ejecución de los planes, programas y proyectos propendiendo por el desarrollo de las actividades misionales fundamentada en principios de eficiencia, transparencia, equidad y calidad de servicio.', 'Fortalecimiento institucional', 'Mejoramiento y efectividad de procesos administrativos y académicos', 'Seguimiento al cumplimiento de la ejecución del sistema integrado de conservación (SIC),  encaminado a establecer la metodología de gestión integral para la conservación y protección del patrimonio natural, cultural y social en la universidad, bajo las pautas del Archivo General de la Nación.', 10.00, 'Realizar el seguimiento al cumplimiento de los programas del  sistema integrado de conservación (SIC),de la universidad, conforme a los lineamientos normativos del AGN.', 10.00, 'Secretaría General', 'PA', '0', 'Implementación y seguimiento del sistema integrado de conservación (SIC).', '(N° de acciones desarrolladas para la  implementación y seguimiento del sistema integrado de conservación (SIC) / N° de acciones contempladas en el  sistema integrado de conservación (SIC).)*100', 'Anual', 'Porcentaje', 'Último valor reportado', 'Para la Implemtación del SIC, se debe cumplir las acciones contempladas 1. (Plan de conservación Documental el cual cuenta con 6 programas) y 2. (Plan de preservación digital a largo plazo).\n\nEstos cuentan con 42 actividades las cuales son las acciones que se deben llevar a cabo para la implementacion y seguimiento del SIC.\n\nPara la puesta en marcha del indicador se establecen las siguientes actividades:\n•Seguimiento a la implementacion de los diferentes programas del SIC\n•Digitalización documentos de los archivos de gestión intervenidos y archivo central.', '[]', '70.7%', 81, '0%', '81%', '81.00', '71.00', 87.65, 71.00, NULL, 'Durante el primer semestre de la vigencia se adelantaron las actividades preparatorias y de seguimiento orientadas al fortalecimiento de la gestión documental institucional, entre las cuales se encuentran la identificación de aspectos a verificar durante los recorridos, el desarrollo de visitas de seguimiento a el archivo central y la formulación de recomendaciones para mejorar las condiciones de organización y conservación documental. De igual manera, se integraron al plan de capacitaciones temas relacionados con los procedimientos de conservación documental como estrategia para la sensibilización, dirigida a los responsables de la custodia y administración de los archivos, promoviendo el conocimiento y la aplicación de los lineamientos institucionales en materia de gestión documental.', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+6, @formulario, 'Implementación y seguimiento del Plan Institucional del programa de gestión documental. (PGD)', 2026, 'Modernización de la Gestión Administrativa', 'Fortalecer la gestión administrativa, el uso eficiente de los recursos financieros, humanos y tecnológicos, la modernización y el mantenimiento de la infraestructura con enfoque a la sostenibilidad ambiental, como apoyo al mejoramiento de las funciones misionales y la prestación de servicios para el desarrollo de la Universidad, y así propiciar la inclusión, la calidad educativa, el bienestar del talento humano, la transparencia y la equidad.', '9. Fortalecer la administración y ejecución de los planes, programas y proyectos propendiendo por el desarrollo de las actividades misionales fundamentada en principios de eficiencia, transparencia, equidad y calidad de servicio.', 'Fortalecimiento institucional', 'Mejoramiento y efectividad de procesos administrativos y académicos', 'Seguimiento al cumplimiento de la ejecución del Programa de Gestión Documental (PGD),  con el objetivo de establecer los lineamientos, estrategias y acciones para la organización, administración, conservación y uso de los documentos producidos y recibidos en la universidad,  en cumplimiento a las directrices del Archivo General de la Nación.', 10.00, 'Realizar el seguimiento al cumplimiento de la ejecución del programa de gestión documental (PGD) de la universidad, conforme a los lineamientos normativos del AGN.', 10.00, 'Secretaría General', 'PA', '0', 'Implementación y seguimiento del Plan Institucional del programa de gestión documental. (PGD)', '(N° de acciones desarrolladas para la  implementación y seguimiento del Plan Institucional del programa de gestión documental. (PGD) / N° de acciones contempladas en el  Plan Institucional del programa de gestión documental. (PGD))*100', 'Anual', 'Porcentaje', 'Último valor reportado', 'Para la implementacion del Programa de Gestion Documental PGD se establecen las siguientes metas a mediano plazo(2 a 3 años):\n1. Implementación de Programas Específicos.  \n2. Implementación de instrumentos archivísticos. \n3. Estandarización de la Gestión Documental en la Universidad. \n4. Incorporar la gestión documental en el alcance de la certificación, las auditorías \ny controles institucionales.\nPara la vigencia 2025 se desarollaran las siguientes actividades:\n•Planificar recursos requeridos para la implementación de los Programas específicos( normalización de formas y formularios electrónicos y gestión de documentos electrónicos).\n•Identificar herramientas tecnológicas necesarias para la implementación de los programas específicos y el desarrollo de software correspondientes ( normalización de formas y formularios electrónicos y gestión de documentos electrónicos).\n•Identificar los documentos vitales o esenciales por series documentales. \n•Asignar valores a los documentos según sus series. \n•Definir los requisitos técnicos, financieros y tecnológicos para implementar el programa de reprografia\n•Establecer los niveles de acceso para los diferentes tipos de documentos, segun su clasificacion y relevancia(reprografia).\n•Inventario de sistemas de informacion institucionales, tecnologias, plataformas tecnologicas\n•Evaluacion de la complejidad tecnica para la aplicacion de los lineamientos del programa especifico(Programa de Gestion Documental E lectronicos PGD)\n•Identificar y clasificar los documentos especiales existentes en la universidad, como fotografías, planos, material audiovisual, piezas de arte, partituras, patentes y software.\n•Evaluar la importancia y valor de los documentos especiales para la universidad, considerando criterios como su relevancia histórica, cultural, científica o administrativa.\n.', '[]', '32%', 44, '0%', '44%', '44.00', '32.00', 72.73, 32.00, NULL, 'Durante el primer semestre de la vigencia, se adelantaron actividades orientadas a la preparación y estructuración del Programa de Gestión Documental (PGD), mediante la definición de aspectos generales, el análisis del alcance del programa y la consolidación de insumos requeridos para el desarrollo de las actividades previstas en el plan de acción.', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+7, @formulario, 'Porcentaje de quejas, reclamos y denuncias resueltas en los términos de ley', 2026, 'Modernización de la Gestión Administrativa', 'Fortalecer la gestión administrativa, el uso eficiente de los recursos financieros, humanos y tecnológicos, la modernización y el mantenimiento de la infraestructura con enfoque a la sostenibilidad ambiental, como apoyo al mejoramiento de las funciones misionales y la prestación de servicios para el desarrollo de la Universidad, y así propiciar la inclusión, la calidad educativa, el bienestar del talento humano, la transparencia y la equidad.', '9. Fortalecer la administración y ejecución de los planes, programas y proyectos propendiendo por el desarrollo de las actividades misionales fundamentada en principios de eficiencia, transparencia, equidad y calidad de servicio.', 'Fortalecimiento institucional', 'Mejoramiento y efectividad de procesos administrativos y académicos', 'Garantizar la relación de la institución con los grupos de interés a través de la identificación y respuesta de las inquietudes y manifestaciones como se describe en la ley 1755 de 2015.', 10.00, 'Medir el porcentaje de oportunidad en la respuesta, indicar la eficiencia en la  resolución de quejas reclamos y denuncias interpuestas', 10.00, 'Secretaría General', 'PA', '0', 'Porcentaje de quejas, reclamos y denuncias resueltas en los términos de ley', '(N° de radicados de PQRSFD resueltas en los términos de ley / N° de radicados de PQRSFD recibidas) * 100', 'Anual', 'Porcentaje', 'Último valor reportado', 'Cumpliendo con lo establecido en el Decreto 103 de 2015, Artículo 52 -\nInformes de solicitudes de acceso a información, el presente indicador se refiere al reporte sobre Peticiones, Quejas, Reclamos, Sugerencias, Denuncias y Felicitaciones (PQRSDF) recibidas y tramitadas por las diferentes dependencias de la Universidad del Atlántico durante el periodo comprendido entre enero y diciembre de 2025, con base en la información generada por el sistema ORFEO.\n\nEl objetivo de este indicador es identificar la respuesta oportuna brindada a\nlos usuarios y proporcionar las herramientas necesarias para definir procesos de mejora continua, tomar medidas que reduzcan los errores y aumenten la calidad del servicio prestado.', '[]', '82%', 85, '0%', '85%', '85.00', '70.00', 82.35, 70.00, NULL, 'Durante el primer semestre de 2026 se evidenció un incremento progresivo en el volumen de PQRSDF, asociado principalmente a la concentración de trámites generada por los retrasos en la contratación del personal administrativo y docente al inicio de la vigencia. Las peticiones continuaron siendo la tipología predominante, representando el mayor porcentaje de las solicitudes recibidas.\n\nEn cuanto a la oportunidad en la atención, el 70 % de las solicitudes fueron resueltas dentro de los términos establecidos, mientras que el porcentaje restante correspondió a solicitudes atendidas con retraso o que permanecían pendientes al cierre del período. La mayor carga operativa se concentró en el Departamento de Admisiones y Registro y la Secretaría General, siendo esta última una de las dependencias con mejor nivel de cumplimiento pese al alto volumen de trámites atendidos.', 'Durante el período evaluado, el desarrollo de las actividades de la Secretaría General se vio afectado por dos factores que incidieron directamente en la capacidad operativa de la dependencia. En primer lugar, la suspensión parcial de las actividades académicas y administrativas hasta mediados del mes de enero, derivada del paro estudiantil y de las alteraciones del orden interno, limitó la ejecución de diversos procesos institucionales y ocasionó el represamiento de trámites. En segundo lugar, los retrasos en la contratación del personal administrativo y docente al inicio de 2026 concentraron en un corto período de tiempo un alto volumen de solicitudes, incrementando significativamente la carga de trabajo una vez se normalizaron las actividades institucionales.', '', 'Frente a este escenario, la Secretaría General fortaleció los mecanismos de coordinación con las diferentes áreas, optimizó la distribución de las actividades, mantuvo la operación de los canales virtuales de atención y realizó seguimiento permanente a los procesos críticos, garantizando la continuidad de los servicios institucionales y mitigando el impacto de estas circunstancias sobre los usuarios internos y externos. Asimismo, continuará impulsando acciones de mejora orientadas a fortalecer la planificación institucional, la articulación entre dependencias y la oportunidad en la contratación del personal, con el propósito de reducir la acumulación de trámites y mejorar los tiempos de respuesta.', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+8, @formulario, 'Cumplimiento acuerdos de garantías', 2026, 'Modernización de la Gestión Administrativa', 'Fortalecer la gestión administrativa, el uso eficiente de los recursos financieros, humanos y tecnológicos, la modernización y el mantenimiento de la infraestructura con enfoque a la sostenibilidad ambiental, como apoyo al mejoramiento de las funciones misionales y la prestación de servicios para el desarrollo de la Universidad, y así propiciar la inclusión, la calidad educativa, el bienestar del talento humano, la transparencia y la equidad.', '8. Fortalecer la gestión administrativa buscando eficiencia, transparencia equidad y calidad de servicio propendiendo por el desarrollo de las funciones misionales.', 'Fortalecimiento institucional', 'Mejoramiento y efectividad de procesos administrativos y académicos', 'Fortalecer la gestión administrativa buscando eficiencia, transparencia equidad y calidad de servicio propendiendo por el desarrollo de las funciones misionales.', 10.00, 'Medir el grado de la gestión con respecto a las garantias institucionales en la vigencia 2026.', 15.00, 'Oficina de Planeación', 'PA', '0', 'Cumplimiento acuerdos de garantías', '(N° actividades ejecutadas/N° de actividades planificadas*) 100', 'Anual', 'Porcentaje', 'Último valor reportado', '', '[]', '0%', 80, '0%', '80%', '80.00', '40.00', 50.00, 40.00, NULL, 'Se ha realizado el seguimiento de las garantias a través de las mesas de seguimiento y solicitudes de información.', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+9, @formulario, 'Porcentaje de implementación de la estrategia de Gobierno Digital', 2026, 'Modernización de la Gestión Administrativa', 'Fortalecer la gestión administrativa, el uso eficiente de los recursos financieros, humanos y tecnológicos, la modernización y el mantenimiento de la infraestructura con enfoque a la sostenibilidad ambiental, como apoyo al mejoramiento de las funciones misionales y la prestación de servicios para el desarrollo de la Universidad, y así propiciar la inclusión, la calidad educativa, el bienestar del talento humano, la transparencia y la equidad.', '4. Fortalecer las plataformas tecnológicas y los sistemas de información para incrementar la eficiencia de los procesos mediante la adecuada planificación e integración de estos bajo condiciones de seguridad y gobernabilidad.', 'Fortalecimiento institucional', 'Modernización de las herramientas tecnológicas y los sistemas de gestión', 'Implementar la estrategia de Gobierno Digital', 12.00, 'Fomentar el cumplimiento de las estrategias definidas por el gobierno nacional para la implementación de Gobierno digital en la institución', 25.00, 'Oficina de Gest. Tec. e Información', 'PDI', '0', 'Porcentaje de implementación de la estrategia de Gobierno Digital', '(N° de componentes implementados/ N° total de componentes) *100', 'Anual', 'Porcentaje', 'Último valor reportado', 'de los 19 componentes, se espera la implementación de 12 para el 2025 que equivalen a un 63%', '[]', '65%', 78, '0%', '78%', '78.00', '68.00', 87.18, 68.00, NULL, 'Durante el primer semestre del 2026 tenemos el logro de instalción de pantallas inteligentes en algunos salones de la universidad y tambien se logro incrementar las licencias y adquirir licenciamiento IA de Google. Se ejecutó el seguimiento periódico a la matriz de políticas de desempeño, identificando un nivel de avance del 68% en las acciones programadas para la vigencia en este periodo se avance con un componente, con un total de 13 de 19 Componentes: \n1. Objetivo de la Politica: X\n2. Funcionalidad de la Politica: X\n3. Elementos de la Politica: X\n4. Actores y/o comite de seguridad de la Información\n5. Relación con el modelo integrado de Planeación y gestión\n6. Revisión de Planes estrategicos: X\n7. Revisión de del estado e implementación de las politicas de gestión y desempeño institucional\n8. Identificación del nivel implementación del marco de arquitectura empresarial: X\n9. Identificación del nivel implementación del modelo de seguridad y privacidad de la información: X\n10. Identificación del nivel implementación del decreto 1413 del 2017: X\n11. Priorización de iniciativas: X\n12. Formulación o actualización del PETI y el modelo de seguridad de la información: X\n13. Aseguramiento de la generación de valor para la entidad y los usuarios: X\n14. Gestión de cambio, sencibilización a la comunidad:X\n15. Diseño Integral de los proyectos:X\n16. Gestion de principio a finX\n17. Definir indicadores de seguimiento para evaluar avance del PETI y el Plan de seguridad de la información\n18. Realizar un autodiagnostico a traves del formato de prueba de FURAG\n19. Realizar un autodiagnostico en materia de seguridad de la información', 'Limitación de recursos financieros para inversión, Insuficiencia y rotación de personal especializado para el soporte', 'La disponibilidad presupuestal y a la capacidad operativa del equipo de TI. La carga operativa de soporte y el déficit de personal especializado han desacelerado el cumplimiento de los componentes', 'Implementar IA en los procesos, uso de los tableros inteligentes como medio educativo', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+10, @formulario, 'Plan de modernización de plataforma tecnológica implementado a 10 años', 2026, 'Modernización de la Gestión Administrativa', 'Fortalecer la gestión administrativa, el uso eficiente de los recursos financieros, humanos y tecnológicos, la modernización y el mantenimiento de la infraestructura con enfoque a la sostenibilidad ambiental, como apoyo al mejoramiento de las funciones misionales y la prestación de servicios para el desarrollo de la Universidad, y así propiciar la inclusión, la calidad educativa, el bienestar del talento humano, la transparencia y la equidad.', '4. Fortalecer las plataformas tecnológicas y los sistemas de información para incrementar la eficiencia de los procesos mediante la adecuada planificación e integración de estos bajo condiciones de seguridad y gobernabilidad.', 'Fortalecimiento institucional', 'Modernización de las herramientas tecnológicas y los sistemas de gestión', 'Modernizar la plataforma tecnológica de la Universidad', 12.00, 'Crear el Plan de modernización de plataforma tecnológica a 10 años', 30.00, 'Oficina de Gest. Tec. e Información', 'PDI', '0', 'Plan de modernización de plataforma tecnológica implementado a 10 años', '(N° de componentes del plan implementados / N° total de componentes del plan) * 100', 'Anual', 'Porcentaje', 'Último valor reportado', 'de los 9 componentes, se espera la implementación de 5 para el 2025, lo que representa un 55%', '[]', '55%', 60, '0%', '60%', '60.00', '55.50', 92.50, 55.50, NULL, 'Se presenta un avance del 55,5% en la formulación de la Hoja de Ruta de Modernización Tecnológica a 10 años, habiendo culminado satisfactoriamente las etapas de Diagnóstico, Definición de Objetivos, Análisis y Evaluación del Problema. Actualmente la entidad se encuentra en la Definición del Plan y Estrategias, lo que formalizará los proyectos de inversión en infraestructura, nube y ciberseguridad necesarios para garantizar la sostenibilidad operativa en el decenio de 9 etapas hemos cumplido 5 completas y estamos iniciando otras dos', 'Incertidumbre presupuestal de largo plazo y la acelerada obsolescencia tecnológica.', 'La constante evolución de las tecnologías emergentes y el marco normativo requiere un esfuerzo continuo de actualización metodológica en las etapas de Análisis, Estrategia y Ejecución,', 'Incorporar en la Etapa 9 (Mejora Continua)', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+11, @formulario, 'Fortalecimiento de los procesos de gestión administrativos y académicos soportados en herramientas tecnológicas', 2026, 'Modernización de la Gestión Administrativa', 'Fortalecer la gestión administrativa, el uso eficiente de los recursos financieros, humanos y tecnológicos, la modernización y el mantenimiento de la infraestructura con enfoque a la sostenibilidad ambiental, como apoyo al mejoramiento de las funciones misionales y la prestación de servicios para el desarrollo de la Universidad, y así propiciar la inclusión, la calidad educativa, el bienestar del talento humano, la transparencia y la equidad.', '4. Fortalecer las plataformas tecnológicas y los sistemas de información para incrementar la eficiencia de los procesos mediante la adecuada planificación e integración de estos bajo condiciones de seguridad y gobernabilidad.', 'Fortalecimiento institucional', 'Modernización de las herramientas tecnológicas y los sistemas de gestión', 'Modernizar la plataforma tecnológica de la Universidad', 12.00, 'Desarrollar de acuerdo a las necesidades de los sistemas, herramientas que permitan la articulación', 20.00, 'Oficina de Gest. Tec. e Información', 'PDI', '0', 'Fortalecimiento de los procesos de gestión administrativos y académicos soportados en herramientas tecnológicas', '(N° Procesos fortalecidos / N° de Procesos Priorizados) *100', 'Anual', 'Porcentaje', 'Último valor reportado', '', '[]', '53%', 55, '0%', '55%', '55.00', '54.00', 98.18, 54.00, NULL, 'Los procesos priorizados para el año 2026  Son:\n\n1.        Administrativos: Gestasoft (RVD)\n2.        Administrativos : Gestasoft ( Gestión de Bienes y Servicios e inventario ) \n3.        Unigest modulo de bonificaciones  \n4.        Académicos Extensión y proyección social \n5.        Sistema de información para unidad de salud\n\nLos procesos priorizados se basan en la estabilización del software Gestasoft  que beneficia a los procesos Administrativos y de implmentación del módulo de Extensión y proyección social con el módulo de extensión, al mismo tiempo nos encontramos en implementaciòn de herramientas en financiera con unigest en los temas de bonificaciones, entre otras, se adiciona el sistema de información de la unidad de salud por requerimientos de ministerio de salud. \nAvance %=2,7/5=54%', 'Las brechas en la curva de aprendizaje y la resistencia al cambio operativa durante las fases de migración de datos y pruebas de usuario, lo que ha ralentizado el cumplimiento de los cronogramas', 'El porcentaje faltante depende de asignación presupuestal', 'Desplegar jornadas intensivas de transferencia de conocimiento y pruebas guiadas con los usuarios clave de Extensión, Bonificaciones y Gestión de Bienes, garantizando la apropiación del software y la calidad de los datos ingresados', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
